// Recursive method to loop trough TreeView nodes and execute an action	internal void TraverseNodes(TreeNodeCollection nodes, Action<SceneTreeNode> action) {	foreach (SceneTreeNode child in nodes) {		action(child);		if (child.Nodes.Count > 0) TraverseNodes(child.Nodes, action);	}}// Use Action	void printText(SceneTreeNode node) {		Console.WriteLine("SceneTreeManager > GetUniqueFolderName > Node:{0} isFolder:{1}", node.Text, node.IsFolder);	}	ST.TraverseAllNodes(printText);// OR local function	// Get unique folder name </summary>	internal static string GetUniqueFolderName(string folderName) {				var folderNames = new List<string>();		//Console.WriteLine("SceneTreeManager > GetUniqueFolderName >");		void getFoldersName(SceneTreeNode node) {			if (node.IsFolder) {				//var tab = "\t".Repeat(node.TabLevel + 1, true)[0];				//Console.WriteLine(tab + "Node:{0} isFolder:{1}", node.Text, node.IsFolder);				folderNames.Add(node.Text);			}		}		ST.TraverseNodes(ST.Nodes, getFoldersName);		return folderNames.GetUniqueName(folderName);	}